"""Activity filter/sort checks against the generated DEV bundle; synthetic only."""
import ast,json
from pathlib import Path
from playwright.sync_api import sync_playwright
base=Path(__file__).resolve().parents[1];tree=ast.parse((base/'scripts/validate-war-scouter.py').read_text());setup=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='setup' for t in n.targets));bundle=(base/'dist/tu-integrated-staging-dev.user.js').read_text();out=base.parent/'development/evidence/war-activity-122';out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 try:
  for label,width,height in [('desktop',1280,900),('portrait',390,844),('landscape',844,390)]:
   context=browser.new_context(viewport={'width':width,'height':height});page=context.new_page();page.route('**/*',lambda route:route.fulfill(status=200,content_type='text/html',body='<main>Torn synthetic fixture</main>') if route.request.url.startswith('https://www.torn.com/') else route.abort());page.goto('https://www.torn.com/index.php');page.evaluate(setup);page.evaluate(bundle);page.locator('#tu-pda-launcher').click();page.locator('[data-tab="modules"]').click();page.locator('.tu-card').filter(has=page.get_by_text('War Tools',exact=True)).locator('button').click();page.locator('.tu-card').filter(has=page.get_by_text('War Organizer',exact=True)).locator('button').click();root=page.locator('#tu-who-panel');page.wait_for_function("document.querySelectorAll('.who-row[data-player-id]').length===6")
   names=lambda:root.locator('.who-list .who-player-name').all_text_contents()
   root.get_by_label('Sort targets',exact=True).select_option('online-first');assert names()==['MapleFox','NightFalcon','SilverWren','EmberWolf','IronHarbor','OceanKite'];root.get_by_label('Sort targets',exact=True).select_option('offline-first');assert names()==['EmberWolf','IronHarbor','OceanKite','SilverWren','MapleFox','NightFalcon']
   root.get_by_label('Activity filter',exact=True).select_option('Online');assert names()==['MapleFox','NightFalcon'];root.get_by_role('button',name='Okay',exact=True).click();assert names()==['NightFalcon'];root.get_by_role('button',name='All',exact=True).click();root.get_by_label('Activity filter',exact=True).select_option('Idle');assert names()==['SilverWren'];root.get_by_label('Activity filter',exact=True).select_option('Offline');assert names()==['EmberWolf','IronHarbor','OceanKite'];root.locator('[data-roster-side="own"]').click();assert names()==['IronHarbor'];root.locator('[data-roster-side="opposing"]').click();assert names()==['EmberWolf','IronHarbor','OceanKite']
   # Controls stay in one compact fixed row without horizontal overflow.
   tools=root.locator('.who-tools');rects=tools.locator('input,select').evaluate_all('(nodes)=>nodes.map(n=>n.getBoundingClientRect().toJSON())');assert max(r['top'] for r in rects)-min(r['top'] for r in rects)<2;assert tools.evaluate('(n)=>n.scrollWidth<=n.clientWidth+1');page.screenshot(path=str(out/(label+'-offline.png')))
   root.get_by_role('button',name='Minimize',exact=True).click();page.locator('#tu-pda-launcher').click();assert root.get_by_label('Activity filter',exact=True).input_value()=='Offline';assert root.get_by_label('Sort targets',exact=True).input_value()=='offline-first'
   page.reload();page.evaluate(setup);page.evaluate(bundle);page.locator('#tu-pda-launcher').click();page.wait_for_function("document.querySelectorAll('.who-row[data-player-id]').length===3");assert root.get_by_label('Activity filter',exact=True).input_value()=='Offline';assert root.get_by_label('Sort targets',exact=True).input_value()=='offline-first';assert names()==['EmberWolf','IronHarbor','OceanKite'];root.get_by_label('Activity filter',exact=True).select_option('Unknown');assert names()==[];context.close()
  (out/'validation.json').write_text(json.dumps({'build':'0.5.42.122-dev','synthetic_only':True,'viewports':['desktop','portrait','landscape'],'checks':['online/offline/idle/unknown activity filters','both activity sort directions','combined Okay filter','own/opposing factions','compact control row without overflow','minimize/launcher and full reload restore selection']},indent=2)+'\n');print('Generated War activity filtering/sorting passed desktop, portrait and landscape.')
 finally:browser.close()
